/* @lc app=leetcode id=3671 lang=kotlin */ class Solution { fun totalBeauty(nums: IntArray): Int = 1_000_000_007L.let { M -> nums.max().let { mx -> Array(mx + 1) { ArrayList<Int>() }.also { ls -> nums.forEach { x -> (1..Math.sqrt(x.toDouble()).toInt()).forEach { d -> if (x % d == 0) ls[d].add(x / d).also { if (d != x / d) ls[x / d].add(d) } } } }.let { ls -> LongArray(mx + 1).also { f -> (1..mx).forEach { g -> if (ls[g].isNotEmpty()) LongArray(mx / g + 2).let { t -> f[g] = ls[g].fold(0L) { tot, v -> ((1 + (generateSequence(v - 1) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } % M)) % M).let { dv -> generateSequence(v) { it + (it and -it) }.takeWhile { it < t.size }.forEach { i -> t[i] = (t[i] + dv) % M }.let { (tot + dv) % M } } } } } }.let { f -> (mx downTo 1).fold(LongArray(mx + 2) to 0L) { (ex, ans), g -> ((f[g] - (2 * g..mx step g).sumOf { ex[it] } % M + M) % M).let { e -> ex.set(g, e).let { ex to (ans + g * e) % M } } }.second.toInt() } } } } }